function validate([nums1, nums2]) {
  if (!Array.isArray(nums1) || !Array.isArray(nums2) || nums1.length !== nums2.length) return 'nums1 and nums2 must have the same length.';
  if (nums1.length < 1 || nums1.length > 100) return 'Each array needs 1 to 100 values.';
  if ([...nums1, ...nums2].some(v => !Number.isInteger(v) || v < 0 || v > 1000)) return 'Every value is an integer from 0 to 1000.';
  const a = [...nums1].sort((p, q) => p - q);
  const b = [...nums2].sort((p, q) => p - q);
  if (a.some((v, i) => b[i] - v !== b[0] - a[0])) return 'nums2 must be nums1 shifted by one integer x.';
  return null;
}

