function generate(rand, size) {
  const int = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  const n = size === 'large' ? 100 : int(1, 6);
  const spread = size === 'large' ? 1000 : int(0, 12);
  const x = size === 'large' ? int(-500, 500) : (rand() < 0.15 ? 0 : int(-20, 20));
  // nums1 values are chosen so that adding x keeps every value inside 0..1000.
  const low = Math.max(0, -x);
  const high = Math.min(1000, 1000 - x);
  const start = rand() < 0.2 ? (rand() < 0.5 ? low : high - Math.min(spread, high - low)) : int(low, high - Math.min(spread, high - low));
  const nums1 = Array.from({ length: n }, () => start + int(0, Math.min(spread, high - low)));
  const nums2 = nums1.map(v => v + x);
  for (let i = nums2.length - 1; i > 0; i--) {
    const j = Math.floor(rand() * (i + 1));
    [nums2[i], nums2[j]] = [nums2[j], nums2[i]];
  }
  return [nums1, nums2];
}
